+    }
+    let target = if a.iter().any(|x| x == "--lib") {
+        "lib".to_string()
+    } else if a.iter().any(|x| x == "--bins") {
+        "bins".to_string()
+    } else if a.iter().any(|x| x == "--doc") {
+        "doc".to_string()
+    } else {
+        a.windows(2).find(|w| w[0] == "--test").map(|w| w[1].clone())?
+    };
+    Some(format!("{dir}:{target}"))
